from __future__ import annotations

"""Mobile V1 active TPR progress presentation.

TPR Progress is a peer Price Review tab and contains only UPCs whose canonical
current observed price state is actively TPR. Suggestions that have not become
the observed current TPR stay in TPR Suggestions and never appear as progress.
"""

_STYLE = r'''
<style id="yipmanV1PriceProgressStyle">
#price .filter4.price-lifecycle-tabs{grid-template-columns:repeat(4,1fr)}
#price .filter4.price-lifecycle-tabs .filterbtn{font-size:9px;padding:3px 2px}
.price-progress{margin-top:6px;border:1px solid #314354;border-radius:11px;background:#101820;text-align:left;overflow:hidden}
.price-progress-summary{width:100%;border:0;background:transparent;color:inherit;padding:8px 9px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;align-items:center;text-align:left}
.price-progress-summary-main{min-width:0}.price-progress-title{font-size:10px;color:#92a3b0;font-weight:1000}.price-progress-purpose{margin-top:2px;color:#a9b6c0;font-size:10px;font-weight:850;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.price-progress-status{font-size:11px;font-weight:1000;color:#d7e8f6;text-align:right;white-space:nowrap}.price-progress-chevron{margin-left:5px;color:#6eaee0}
.price-progress-body{display:none;border-top:1px solid #293744;padding:8px 9px 9px}.price-progress.open .price-progress-body{display:block}
.price-progress-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:5px}.price-progress-grid+.price-progress-grid{margin-top:5px}.price-progress-grid>div{border:1px solid #293744;border-radius:9px;background:#0d151c;padding:6px 4px;text-align:center;min-width:0}
.price-progress-grid b{display:block;color:#7d8f9d;font-size:7px}.price-progress-grid span{display:block;margin-top:2px;font-size:11px;font-weight:1000;overflow-wrap:anywhere}
.price-progress-reason{margin-top:6px;color:#abb8c3;font-size:10px;line-height:1.28;font-weight:760}.price-progress-next{margin-top:6px;border-top:1px solid #293744;padding-top:6px;color:#83c5f2;font-size:9px;font-weight:950}
.tpr-progress-card{border-left:4px solid #7a5ba6!important}.tpr-progress-card .actionbox{border-color:#5c4677!important;background:#171321!important}.tpr-progress-card .progress-state{font-size:10px;font-weight:1000;color:#d7c3f0}.tpr-progress-card .progress-decision{cursor:pointer}
</style>
'''

_SCRIPT_HELPERS = r'''
let tprProgressLoaded=false;
let tprProgressLoading=false;
let tprProgressByUpc=new Map();
function progressUpcKey(v){const d=String(v??'').replace(/\D/g,'').replace(/^0+/,'');return d||''}
function progressNum(v){if(v===null||v===undefined||v==='')return null;const n=Number(v);return Number.isFinite(n)?n:null}
function pctText(v){const n=Number(v);if(!Number.isFinite(n))return '—';return (n>0?'+':'')+n.toFixed(1)+'%'}
function dayText(v){const n=Number(v);return Number.isFinite(n)?n.toFixed(n%1?1:0):'—'}
function samePrice(a,b){const x=progressNum(a),y=progressNum(b);return x!==null&&y!==null&&Math.abs(x-y)<0.011}
function progressCurrentType(r){return String(r?.current_price_type??r?.current_type??r?.observed_price_type??r?.price_type??'').trim().toUpperCase()}
function progressTargetType(r){try{return String(priceType(r)||'').trim().toUpperCase()}catch(_){return''}}
function progressActivation(r,p){const current=progressNum(currentPrice(r)),target=progressNum(suggestedPrice(r)),currentType=progressCurrentType(r),targetType=progressTargetType(r),backendPrice=progressNum(p?.current_price??p?.tpr_price??p?.active_price);const priceChangeRequired=current!==null&&target!==null&&!samePrice(current,target),backendPriceMismatch=backendPrice!==null&&current!==null&&!samePrice(backendPrice,current),typeChangeRequired=!!currentType&&!!targetType&&currentType!==targetType&&targetType!=='KEEP';return{active:!priceChangeRequired&&!backendPriceMismatch&&!typeChangeRequired,current,target,currentType,targetType,backendPrice,priceChangeRequired,backendPriceMismatch,typeChangeRequired}}
function isActiveTprProgress(p){const t=progressCurrentType(p);if(t)return t==='TPR';const active=String(p?.status??p?.tpr_status??p?.lifecycle_status??'').toUpperCase();return active==='ACTIVE'||active==='TPR_ACTIVE'}
async function loadTprProgress(){if(tprProgressLoaded||tprProgressLoading)return;tprProgressLoading=true;try{const d=await api('/v1/yipman/current-tpr-review?category=ALL&limit=1000');const rows=d?.rows||[];tprProgressByUpc=new Map();rows.forEach(x=>{const k=progressUpcKey(x?.upc??x?.ean_upc??x?.ean);if(k)tprProgressByUpc.set(k,x)});tprProgressLoaded=true}catch(_){tprProgressLoaded=false}finally{tprProgressLoading=false}}
function tprProgressDecision(p){const code=String(p?.recommendation_code||p?.recommendation_label||'CONTINUE').toUpperCase().replaceAll('_',' ');const next=p?.suggested_regular_price??p?.suggested_tpr_price;const label=code.includes('CANCEL')||code.includes('END')?'END TPR':code.includes('LOWER')?'LOWER TPR':code.includes('RAISE')?'RAISE TPR':code.includes('REG')?'RETURN TO REG':'KEEP TPR';return next!=null?label+' '+money(next):label}
function tprProgressState(p){const raw=String(p?.progress_status??p?.pacing_status??p?.sell_through_status??p?.recommendation_status??'').toUpperCase();if(raw.includes('BEHIND'))return'BEHIND';if(raw.includes('AHEAD'))return'AHEAD';if(raw.includes('TRACK'))return'ON TRACK';const clear=progressNum(p?.projected_days_to_clear_oh),remain=progressNum(p?.days_remaining??p?.remaining_days_to_threshold);if(clear!==null&&remain!==null)return clear<=remain?'ON TRACK':'BEHIND';return'ACTIVE'}
function activeTprProgressHtml(p){const up=String(p?.upc??p?.ean_upc??p?.ean??'—'),name=String(p?.item_name??p?.upc_name??p?.description??p?.name??'ACTIVE TPR'),fam=String(p?.family??p?.family_article??p?.family_id??'—'),purpose=String(p?.tpr_purpose_label??p?.tpr_purpose??'TPR').replaceAll('_',' '),state=tprProgressState(p),decision=tprProgressDecision(p),cur=p?.current_price??p?.tpr_price??p?.active_price,reg=p?.original_regular_price??p?.baseline_regular_price??p?.regular_price,days=p?.completed_tpr_days??p?.tpr_supported_days??p?.current_behavior?.supported_days??p?.post_supported_days,vel=p?.velocity_lift_pct,gp=p?.gp_day_lift_pct,tprGp=p?.tpr_gp_per_day_3d??p?.current_behavior?.gp_per_day_current_cost,baseGp=p?.baseline_gp_per_day_current_cost??p?.baseline_behavior?.gp_per_day_current_cost,ohStart=p?.tpr_start_oh??p?.starting_oh??p?.effective_oh_at_start,ohNow=p?.effective_oh??p?.current_oh,qty=p?.tpr_sold_qty??p?.sold_qty_since_tpr??p?.qty_sold_tpr,clear=p?.projected_days_to_clear_oh,need=p?.required_velocity_to_clear,actual=p?.tpr_velocity??p?.current_behavior?.velocity??p?.current_velocity,remain=p?.days_remaining??p?.remaining_days_to_threshold,start=p?.tpr_start_date??p?.start_date,end=p?.tpr_end_date??p?.end_date??p?.freshness_threshold_date,reason=String(p?.recommendation_reason||'Active TPR lifecycle tracking on completed valid POS days.');return `<div class="direct-card tpr-progress-card"><div class="row space"><div><div class="result-name">${esc(name)}</div><div class="action-meta">UPC ${esc(up)} · Family ${esc(fam)} · ${esc(purpose)}</div></div><span class="pill blue">ACTIVE TPR</span></div><div class="actionbox progress-decision"><div class="action-label">PRIMARY DECISION · CURRENT TPR PROGRESS</div><div class="action-value">${esc(decision)}</div><div class="why"><b>Status:</b> <span class="progress-state">${esc(state)}</span> · ${esc(reason)}</div></div><div class="summary3"><div class="stat"><b>REG → TPR</b><span>${reg==null?'—':money(reg)} → ${cur==null?'—':money(cur)}</span></div><div class="stat"><b>VALID DAYS</b><span>${esc(dayText(days))}</span></div><div class="stat"><b>EFF OH</b><span>${ohNow==null?'—':esc(fmt(ohNow,1))}</span></div></div><div class="price-progress open"><div class="price-progress-body" style="display:block;border-top:0"><div class="price-progress-grid"><div><b>START OH</b><span>${ohStart==null?'—':esc(fmt(ohStart,1))}</span></div><div><b>SOLD ON TPR</b><span>${qty==null?'—':esc(fmt(qty,1))}</span></div><div><b>REMAINING DAYS</b><span>${esc(dayText(remain))}</span></div><div><b>ACTUAL VELOCITY</b><span>${actual==null?'—':esc(fmt(actual,1))+'/day'}</span></div><div><b>REQ VELOCITY</b><span>${need==null?'—':esc(fmt(need,1))+'/day'}</span></div><div><b>DAYS TO CLEAR</b><span>${esc(dayText(clear))}</span></div></div><div class="price-progress-grid"><div><b>VELOCITY Δ</b><span>${esc(pctText(vel))}</span></div><div><b>GP$/DAY Δ</b><span>${esc(pctText(gp))}</span></div><div><b>TPR GP$/DAY</b><span>${tprGp==null?'—':money(tprGp)}</span></div><div><b>BASE GP$/DAY</b><span>${baseGp==null?'—':money(baseGp)}</span></div><div><b>START</b><span>${esc(start||'—')}</span></div><div><b>END / THRESHOLD</b><span>${esc(end||'—')}</span></div></div><div class="price-progress-next">Only currently observed TPR UPCs · completed valid POS days · tap Primary Decision for Why & Evidence</div></div></div></div>`}
function renderActiveTprProgressTab(){const q=$('#priceQueue');if(!q)return;if(!tprProgressLoaded){q.innerHTML='<div class="loading">Loading current TPR progress…</div>';loadTprProgress().then(()=>{if(pf==='tprprogress')renderPrice()});return}const rows=[...tprProgressByUpc.values()].filter(isActiveTprProgress);$('#priceActions').textContent=rows.length;$('#priceUrgent').textContent=rows.filter(x=>tprProgressState(x)==='BEHIND').length;$('#priceFamilies').textContent=new Set(rows.map(x=>x?.family??x?.family_article??x?.family_id).filter(Boolean)).size;q.innerHTML=rows.map(activeTprProgressHtml).join('')||'<div class="empty">No UPC is currently on active TPR.</div>'}
function priceProgressHtml(r){const p=tprProgressByUpc.get(progressUpcKey(upcOf(r))),activation=progressActivation(r,p||{}),hasTarget=activation.target!==null;if(!p&&!hasTarget)return'';if(!activation.active)return'';if(!p)return'';const rec=String(p?.recommendation_label||p?.recommendation_code||'OBSERVE').replaceAll('_',' '),phase=String(p?.monitoring_phase||'LEARNING').replaceAll('_',' '),purpose=String(p?.tpr_purpose_label||p?.tpr_purpose||'TPR TEST').replaceAll('_',' '),gp=p?.gp_day_lift_pct,vel=p?.velocity_lift_pct,days=p?.completed_tpr_days??p?.tpr_supported_days??p?.current_behavior?.supported_days??p?.post_supported_days,tprGp=p?.tpr_gp_per_day_3d??p?.current_behavior?.gp_per_day_current_cost,baseGp=p?.baseline_gp_per_day_current_cost??p?.baseline_behavior?.gp_per_day_current_cost,next=p?.suggested_regular_price??p?.suggested_tpr_price,nextLabel=p?.suggested_regular_price!=null?'NEW REG':(p?.suggested_tpr_price!=null?'NEXT TPR':'NEXT'),clearDays=p?.projected_days_to_clear_oh,needVel=p?.required_velocity_to_clear,reason=String(p?.recommendation_reason||'Tracking active test on completed valid POS days.'),daySummary=Number.isFinite(Number(days))?`DAY ${dayText(days)}/7`:'ACTIVE';return `<div class="price-progress"><button type="button" class="price-progress-summary" data-progress-toggle><div class="price-progress-summary-main"><div class="price-progress-title">TEST ACTIVE · ${esc(daySummary)}</div><div class="price-progress-purpose">${esc(purpose)} · GP$/DAY ${esc(pctText(gp))}</div></div><div class="price-progress-status">${esc(rec)}<span class="price-progress-chevron">⌄</span></div></button><div class="price-progress-body"><div class="price-progress-grid"><div><b>VALID DAYS</b><span>${esc(dayText(days))}</span></div><div><b>VELOCITY Δ</b><span>${esc(pctText(vel))}</span></div><div><b>GP$/DAY Δ</b><span>${esc(pctText(gp))}</span></div><div><b>TEST GP$/DAY</b><span>${tprGp==null?'—':money(tprGp)}</span></div><div><b>BASE GP$/DAY</b><span>${baseGp==null?'—':money(baseGp)}</span></div><div><b>${esc(nextLabel)}</b><span>${next==null?'—':money(next)}</span></div></div>${(clearDays!=null||needVel!=null)?`<div class="price-progress-grid"><div><b>DAYS TO CLEAR</b><span>${esc(dayText(clearDays))}</span></div><div><b>REQ VELOCITY</b><span>${needVel==null?'—':esc(fmt(needVel,1))+'/day'}</span></div><div><b>CURRENT TEST</b><span>${esc(String(p?.current_price??p?.tpr_price??'—'))}</span></div></div>`:''}<div class="price-progress-reason">${esc(reason)}</div><div class="price-progress-next">Backend lifecycle tracking · completed valid data days only</div></div></div>`}
function wirePriceProgressToggles(){document.querySelectorAll('#price [data-progress-toggle]').forEach(btn=>{if(btn.dataset.progressBound==='1')return;btn.dataset.progressBound='1';btn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();const p=btn.closest('.price-progress');if(p)p.classList.toggle('open')})})}
'''


def polish_price_progress_html(html: str) -> str:
    marker="yipmanV1PriceProgress"
    if marker in html:return html
    # Price lifecycle tabs: REG / TPR Suggestions / TPR Progress / Clearance.
    old='<div class="filter4"><button class="filterbtn" data-pf="reg">REG</button><button class="filterbtn" data-pf="tpr">TPR</button><button class="filterbtn" data-pf="clearance">Clearance</button><button class="filterbtn" data-pf="sale">SALE</button></div>'
    new='<div class="filter4 price-lifecycle-tabs"><button class="filterbtn" data-pf="reg">REG</button><button class="filterbtn" data-pf="tpr">TPR Suggestions</button><button class="filterbtn" data-pf="tprprogress">TPR Progress</button><button class="filterbtn" data-pf="clearance">Clearance</button></div>'
    html=html.replace(old,new,1)
    anchor="async function loadPrice(){"
    if anchor in html:html=html.replace(anchor,_SCRIPT_HELPERS+"\n"+anchor,1)
    # TPR Progress is rendered from authoritative current-tpr-review rows, not suggestion rows.
    render_anchor="function renderPrice(){const rows=priceRows.filter"
    if render_anchor in html:html=html.replace(render_anchor,"function renderPrice(){if(pf==='tprprogress'){renderActiveTprProgressTab();$$('[data-pf]').forEach(b=>b.classList.toggle('active',b.dataset.pf===pf));return}const rows=priceRows.filter",1)
    old_tail="}renderPrice()}\nfunction actionablePrice"
    new_tail="}renderPrice();wirePriceProgressToggles();if(!tprProgressLoaded&&!tprProgressLoading){loadTprProgress().then(()=>{renderPrice();wirePriceProgressToggles()}).catch(()=>{})}}\nfunction actionablePrice"
    if old_tail in html:html=html.replace(old_tail,new_tail,1)
    old_card="</div><button class=\"ignore\" data-pi=\"${esc(key)}\">Ignore 12h</button></div>`"
    new_card="</div>${priceProgressHtml(r)}<button class=\"ignore\" data-pi=\"${esc(key)}\">Ignore 12h</button></div>`"
    if old_card in html:html=html.replace(old_card,new_card,1)
    html=html.replace("$$('[data-pi]').forEach(b=>b.onclick=()=>{setIgnore(b.dataset.pi);renderPrice()})}}","$$('[data-pi]').forEach(b=>b.onclick=()=>{setIgnore(b.dataset.pi);renderPrice()});wirePriceProgressToggles()}}",1)
    html=html.replace("</style>","</style>\n"+_STYLE,1)
    html=html.replace("</head>",f'<meta name="{marker}" content="1">\n</head>',1)
    return html
